//! zombie.Lua.LuaManager.Exposer and se.krka.kahlua.integration.expose.LuaJavaClassExposer: the Java classes and
//! global functions the game's Lua sees.
//!
//! The original builds this by reflection over ~1,000 classes. Here the shape comes from a measurement of the
//! original (`exposed_table.rs`, generated by tools/gen_lua_expose.py): for each class the port exposes so far, its
//! statics table (`class`, static methods, public static fields, `new`) in the original's key order and the names
//! of its methods; and every global function of LuaManager.GlobalObject. A method the port has not written yet is
//! still there and raises "not ported" when called (PLACEHOLDER); a class outside the table is absent.
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::{Rc, Weak};

use super::exposed_methods;
use super::exposed_table::{CLASSES, GLOBALS, JAVA_CLASSES};
use super::lua_event_manager::EventRegistry;
use super::lua_manager::{run_lua, Loader};
use crate::se::krka::kahlua::j2se::j2se_platform::J2SEPlatform;
use crate::se::krka::kahlua::j2se::kahlua_table_impl::KahluaTableImpl;
use crate::se::krka::kahlua::vm::coroutine::FrameRef;
use crate::se::krka::kahlua::vm::kahlua_thread::KahluaThread;
use crate::se::krka::kahlua::vm::kahlua_util::{get_class_metatables, get_or_create_table};
use crate::se::krka::kahlua::vm::object::{
    classes, JavaClass, JavaFunction, Object, TableRef, Throwable, ThrowableObject, Userdata, R,
};

/// One entry of a statics table, as measured.
#[derive(Clone, Copy, Debug)]
pub enum Static {
    /// `class`: the class object.
    Class,
    /// A static method or the constructors (`new`), with the number of overloads.
    Method(u8),
    /// An enum constant: its class (index in JAVA_CLASSES), name and ordinal.
    Enum(u16, &'static str, i32),
    /// An object a public static field holds: its class, and for a registry constant
    /// (`registerBase("Id")`) the id it was registered with ("" otherwise).
    Object(u16, &'static str),
    Number(u64),
    Str(&'static str),
    Bool(bool),
    /// The statics table of a nested class.
    Nested(&'static str),
}

/// One exposed class.
pub struct Exposed {
    /// Index in JAVA_CLASSES.
    pub class: u16,
    /// The global (`env[SimpleName]`) that holds the statics table, when it does.
    pub global: Option<&'static str>,
    /// Whether the class has a metatable in `__classmetatables` (instances can call its methods).
    pub has_metatable: bool,
    pub statics: &'static [(&'static str, Static)],
    /// The method table (`__index`): names in order, with their overload counts.
    pub methods: &'static [(&'static str, u8)],
}

/// The class called `name` among the exposed ones (and the classes of their static values); `java.lang.Object`
/// otherwise.
pub fn class_named(name: &str) -> &'static JavaClass {
    JAVA_CLASSES
        .iter()
        .find(|c| c.name == name)
        .unwrap_or(&classes::OBJECT)
}

static GLOBAL_OBJECT_CLASS: JavaClass = JavaClass {
    name: "zombie.Lua.LuaManager$GlobalObject",
    superclass: Some(&classes::OBJECT),
    interfaces: &[],
};
static LUA_JAVA_INVOKER_CLASS: JavaClass = JavaClass {
    name: "se.krka.kahlua.integration.expose.LuaJavaInvoker",
    superclass: Some(&classes::OBJECT),
    interfaces: &[&classes::JAVA_FUNCTION],
};
static MULTI_LUA_JAVA_INVOKER_CLASS: JavaClass = JavaClass {
    name: "se.krka.kahlua.integration.expose.MultiLuaJavaInvoker",
    superclass: Some(&classes::OBJECT),
    interfaces: &[&classes::JAVA_FUNCTION],
};

/// What the original keeps in Java statics and the exposed API reaches: the singletons the scripts call into,
/// the values the exposer published, and the LuaManager state (`RunLua`) some of them use.
pub struct JavaStatics {
    pub platform: Rc<J2SEPlatform>,
    pub loader: Rc<RefCell<Loader>>,
    /// LuaManager.env (weak: the environment holds the functions that hold this).
    pub env: Weak<RefCell<KahluaTableImpl>>,
    /// The values of public static fields, by class and field name, so that Java code returns the same objects.
    fields: RefCell<HashMap<(&'static str, &'static str), Object>>,
    /// Object identity of the Java singletons (`X.instance`, `X.getInstance()`, ...), by class name.
    singletons: RefCell<HashMap<&'static str, Object>>,
    /// LuaEventManager's event list (`Events`).
    pub events: Rc<EventRegistry>,
    /// Java state behind the exposed classes, owned by their ports.
    pub state: super::exposed_methods::State,
    /// Core.debug
    pub debug: bool,
}

impl JavaStatics {
    pub fn new(
        platform: Rc<J2SEPlatform>,
        loader: Rc<RefCell<Loader>>,
        env: &TableRef,
        events: Rc<EventRegistry>,
    ) -> Rc<JavaStatics> {
        Rc::new(JavaStatics {
            platform,
            loader,
            env: Rc::downgrade(env),
            fields: RefCell::new(HashMap::new()),
            singletons: RefCell::new(HashMap::new()),
            events,
            state: Default::default(),
            debug: false,
        })
    }

    /// LuaManager.env
    pub fn env(&self) -> R<TableRef> {
        self.env
            .upgrade()
            .ok_or_else(|| Throwable::runtime("LuaManager.env is gone"))
    }

    /// The value of a public static field the exposer published (`IsoDirections.N`, ...).
    pub fn field(&self, class: &str, name: &str) -> Object {
        self.fields
            .borrow()
            .iter()
            .find(|((c, n), _)| *c == class && *n == name)
            .map(|(_, v)| v.clone())
            .unwrap_or_default()
    }

    /// zombie.Lua.LuaManager.RunLua(String)
    pub fn run_lua(&self, thread: &mut KahluaThread, filename: &str) -> R<Object> {
        let env = self.env()?;
        run_lua(&self.loader, &self.platform, &env, thread, filename)
    }

    /// The one object of a Java singleton class, made by `make` on first use.
    pub fn singleton(&self, class: &'static str, make: impl FnOnce() -> Object) -> Object {
        if let Some(o) = self.singletons.borrow().get(class) {
            return o.clone();
        }
        let o = make();
        self.singletons.borrow_mut().insert(class, o.clone());
        o
    }

    /// zombie.core.logger.ExceptionLogger.logException(Throwable): the game's log (kept with the loader's).
    pub fn log_exception(&self, t: &Throwable) {
        let text = ThrowableObject(t.clone()).java_to_string();
        self.loader
            .borrow_mut()
            .log
            .push(format!("ExceptionLogger: {text}"));
    }
}

/// A constant of a Java enum as a Lua value (one object per constant and Lua state).
pub struct JavaEnum {
    pub class: &'static JavaClass,
    pub name: &'static str,
    pub ordinal: i32,
}

impl Userdata for JavaEnum {
    fn class(&self) -> &'static JavaClass {
        self.class
    }
    /// Enum.toString: the constant's name.
    fn java_to_string(&self) -> String {
        self.name.to_string()
    }
    fn as_any(&self) -> &dyn std::any::Any {
        self
    }
}

/// An object a public static field holds that the port has no richer type for: a registry constant
/// (CharacterTrait.AXEMAN, ItemKey.Container.KEY_RING, ...) with the id it was registered with, or an opaque value
/// (a boxed Integer, a lambda) that only keeps its class and identity.
pub struct JavaObject {
    pub class: &'static JavaClass,
    pub id: &'static str,
}

impl Userdata for JavaObject {
    fn class(&self) -> &'static JavaClass {
        self.class
    }
    fn java_to_string(&self) -> String {
        exposed_methods::object_to_string(self)
            .unwrap_or_else(|| format!("{}@{:x}", self.class.name, identity_hash_code_of(self)))
    }
    fn as_any(&self) -> &dyn std::any::Any {
        self
    }
}

fn identity_hash_code_of<T>(t: &T) -> i32 {
    ((t as *const T as usize >> 4) & 0x7fff_ffff) as i32
}

/// How an exposed call fails, which decides what Lua sees.
#[derive(Debug)]
pub enum Fail {
    /// Thrown into Lua: the argument check of LuaJavaInvoker.prepareCall (MethodArguments.assertValid throws a
    /// RuntimeException with the failure), or a call the port has not written.
    Lua(Throwable),
    /// An exception of the Java method itself: se.krka.kahlua.integration.expose.caller.MethodCaller.call catches
    /// every Throwable of `method.invoke`, logs it (ExceptionLogger) and pushes no result, so Lua gets nothing back
    /// and goes on.
    Java(Throwable),
}

impl From<Throwable> for Fail {
    fn from(t: Throwable) -> Fail {
        Fail::Java(t)
    }
}

/// What an exposed method returns: the number of results it pushed, or how it failed.
pub type Ret = Result<i32, Fail>;

/// The implementation of an exposed method: (statics, thread, frame, number of arguments) -> number of results.
pub type Imp = fn(&Rc<JavaStatics>, &mut KahluaThread, &FrameRef, i32) -> Ret;

/// se.krka.kahlua.integration.expose.LuaJavaInvoker (one method) or MultiLuaJavaInvoker (overloads, which the
/// implementation tells apart by its arguments).
pub struct Invoker {
    pub class: &'static JavaClass,
    pub name: &'static str,
    pub overloads: u8,
    /// An instance method: the first argument must be an instance of `class`.
    pub has_self: bool,
    statics: Rc<JavaStatics>,
    imp: Option<Imp>,
}

impl Invoker {
    pub fn new(
        class: &'static JavaClass,
        name: &'static str,
        overloads: u8,
        has_self: bool,
        statics: &Rc<JavaStatics>,
    ) -> Invoker {
        let imp = if std::ptr::eq(class, &GLOBAL_OBJECT_CLASS) {
            exposed_methods::global(name)
        } else {
            exposed_methods::method(class.name, name, has_self)
        };
        Invoker {
            class,
            name,
            overloads,
            has_self,
            statics: statics.clone(),
            imp,
        }
    }
}

/// `clazz.isInstance(o)` for the classes the port models: a userdata of that class (by name).
pub fn is_instance(o: &Object, class: &JavaClass) -> bool {
    match o {
        Object::Userdata(u) => u.class().name == class.name,
        _ => false,
    }
}

impl JavaFunction for Invoker {
    /// se.krka.kahlua.integration.expose.LuaJavaInvoker.call
    fn call(&self, thread: &mut KahluaThread, cf: &FrameRef, n: i32) -> R<i32> {
        if self.has_self {
            let s = if n <= 0 { Object::Nil } else { cf.get(0) };
            if !is_instance(&s, self.class) {
                return Err(Throwable::runtime(format!(
                    "{}: Expected a method call but got a function call.",
                    self.name
                )));
            }
        }
        match self.imp {
            Some(f) => match f(&self.statics, thread, cf, n) {
                Ok(results) => Ok(results),
                Err(Fail::Lua(t)) => Err(t),
                Err(Fail::Java(t)) => {
                    self.statics.log_exception(&t);
                    Ok(0)
                }
            },
            None => Err(Throwable::runtime(format!(
                "not ported: {}.{}",
                self.class.name, self.name
            ))),
        }
    }
    /// LuaJavaInvoker.toString is the method name; MultiLuaJavaInvoker has Object.toString.
    fn java_to_string(&self) -> String {
        if self.overloads > 1 {
            format!(
                "{}@{:x}",
                MULTI_LUA_JAVA_INVOKER_CLASS.name,
                identity_hash_code_of(self)
            )
        } else {
            self.name.to_string()
        }
    }
    fn class(&self) -> &'static JavaClass {
        if self.overloads > 1 {
            &MULTI_LUA_JAVA_INVOKER_CLASS
        } else {
            &LUA_JAVA_INVOKER_CLASS
        }
    }
}

/// LuaJavaClassExposer.createTableStructure: `env.a.b.C` for "a.b.C" (`$` counts as a dot), made on the way.
fn create_table_structure(env: &TableRef, name: &str) -> R<TableRef> {
    let mut base = env.clone();
    for s in name.replace('$', ".").split('.') {
        base = get_or_create_table(&base, s)?;
    }
    Ok(base)
}

/// zombie.Lua.LuaManager.Exposer.exposeAll for the measured classes, then exposeGlobalFunctions(GlobalObject).
/// Per class: setupMetaTables + exposeMethods (an instance method table under `__index`), then exposeStatics.
/// The super-metatable chain of the method tables is not set (each class has every inherited public method in
/// its own table, as getMethods() lists them). Keyboard/Mouse key numbers come with the measured statics.
pub fn expose_all(statics: &Rc<JavaStatics>, thread: &mut KahluaThread) -> R<()> {
    let env = statics.env()?;
    let platform = statics.platform.clone();
    let metatables = get_class_metatables(&env)?;
    for c in CLASSES.iter() {
        let class = &JAVA_CLASSES[usize::from(c.class)];
        if !c.has_metatable {
            continue;
        }
        let metatable = platform.new_table();
        let index = platform.new_table();
        KahluaTableImpl::rawset(
            &metatable,
            Object::str("__index"),
            Object::Table(index.clone()),
        );
        for (name, overloads) in c.methods {
            KahluaTableImpl::rawset(
                &index,
                Object::str(name),
                Object::Function(Rc::new(Invoker::new(
                    class, name, *overloads, true, statics,
                ))),
            );
        }
        KahluaTableImpl::rawset(
            &metatables,
            platform.class_object(class),
            Object::Table(metatable),
        );
    }
    for c in CLASSES.iter() {
        let class = &JAVA_CLASSES[usize::from(c.class)];
        let container = create_table_structure(&env, class.name)?;
        if let Some(g) = c.global {
            if KahluaTableImpl::rawget(&env, &Object::str(g))?.is_nil() {
                KahluaTableImpl::rawset(&env, Object::str(g), Object::Table(container.clone()));
            }
        }
        for (key, s) in c.statics {
            let value = match *s {
                Static::Class => platform.class_object(class),
                Static::Method(n) => {
                    Object::Function(Rc::new(Invoker::new(class, key, n, false, statics)))
                }
                Static::Enum(ci, name, ordinal) => Object::Userdata(Rc::new(JavaEnum {
                    class: &JAVA_CLASSES[usize::from(ci)],
                    name,
                    ordinal,
                })),
                Static::Object(ci, id) => exposed_methods::static_object(
                    statics,
                    thread,
                    class.name,
                    key,
                    &JAVA_CLASSES[usize::from(ci)],
                    id,
                )?,
                Static::Number(bits) => Object::Number(f64::from_bits(bits)),
                Static::Str(s) => Object::str(s),
                Static::Bool(b) => Object::Boolean(b),
                Static::Nested(n) => Object::Table(create_table_structure(&env, n)?),
            };
            if matches!(s, Static::Enum(..) | Static::Object(..)) {
                statics
                    .fields
                    .borrow_mut()
                    .insert((class.name, key), value.clone());
            }
            KahluaTableImpl::rawset(&container, Object::str(key), value);
        }
    }
    for (name, overloads) in GLOBALS.iter() {
        if KahluaTableImpl::rawget(&env, &Object::str(name))?.is_nil() {
            KahluaTableImpl::rawset(
                &env,
                Object::str(name),
                Object::Function(Rc::new(Invoker::new(
                    &GLOBAL_OBJECT_CLASS,
                    name,
                    *overloads,
                    false,
                    statics,
                ))),
            );
        }
    }
    Ok(())
}
